draw:
var g = 9.8;
var mu = p.muk, m = p.mass;
function T(a) { return mu * m * g / (Math.cos(a) + mu * Math.sin(a)); }
var best = Math.atan(mu);
var Tbest = T(best);
var th = p.angle * Math.PI / 180;
var Tnow = T(th);

var pad = 40;
var x0 = pad, x1 = W - 14;
var y0 = H - 34, y1 = 26;
var amax = 80 * Math.PI / 180;
var tmax = Math.max(T(0), T(amax)) * 1.12;

ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y0); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0, y1); ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("rope angle above horizontal (deg)", (x0 + x1) / 2, H - 12);
ctx.textAlign = "left";
ctx.fillText("tension (N)", x0 - 30, y1 - 10);

function PX(a) { return x0 + (a / amax) * (x1 - x0); }
function PY(v) { return y0 - (v / tmax) * (y0 - y1); }

ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var a = amax * i / 120;
  if (i === 0) ctx.moveTo(PX(a), PY(T(a))); else ctx.lineTo(PX(a), PY(T(a)));
}
ctx.stroke();

ctx.setLineDash([3, 4]);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(PX(best), y0); ctx.lineTo(PX(best), PY(Tbest)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, PY(Tbest)); ctx.lineTo(PX(best), PY(Tbest)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(PX(th), PY(Tnow), 5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("min at arctan(mu) = " + (best * 180 / Math.PI).toFixed(1) + " deg", PX(best) + 6, PY(Tbest) - 8);
ctx.textAlign = "center";
ctx.fillText("0", x0, y0 + 16);
ctx.fillText("80", x1 - 6, y0 + 16);

out.note = "at " + p.angle.toFixed(0) + " deg you need " + Tnow.toFixed(1) + " N; the best angle " + (best * 180 / Math.PI).toFixed(1) + " deg needs " + Tbest.toFixed(1) + " N";
